#!/usr/bin/env python3
"""Recompute ground truth for CSX-008_Q1 from local CSX-008 package files."""

from __future__ import annotations

import json
from datetime import date
from pathlib import Path
from typing import Any


TASK_ID = "CSX-008_Q1"
PACKAGE_ID = "CSX-008"

EVENT_WINDOW_PATH = (
    "data/event_reports/"
    "event_reports_003_Locked_event_anchor_2019-2020_Australian_extreme_heat_during_Black_Summer.json"
)
DNBR_PATH = "data/physical_hazard/physical_hazard_008_Sentinel-2_SR_Harmonized_dNBR.json"
EMBEDDING_PATH = "data/remote_sensing/remote_sensing_003_Google_Satellite_Embedding_annual_cosine-change_stats.json"
OPENMETEO_PATH = "data/physical_hazard/physical_hazard_001_Open-Meteo_historical_archive.json"


def repo_root() -> Path:
    return Path(__file__).resolve().parents[3]


def package_root() -> Path:
    return repo_root() / "event_packages" / "standard_event_packages" / "packages" / PACKAGE_ID


def read_json(root: Path, rel_path: str) -> Any:
    return json.loads((root / rel_path).read_text(encoding="utf-8"))


def parse_date(value: str) -> date:
    return date.fromisoformat(value)


def inclusive_days(start: str, end: str) -> int:
    return (parse_date(end) - parse_date(start)).days + 1


def overlap_days(start_a: str, end_a: str, start_b: str, end_b: str) -> int:
    start = max(parse_date(start_a), parse_date(start_b))
    end = min(parse_date(end_a), parse_date(end_b))
    if start > end:
        return 0
    return (end - start).days + 1


def round6(value: float) -> float:
    return round(float(value), 6)


def build_rubric() -> dict[str, Any]:
    return {
        "total_points": 20,
        "criteria": [
            {
                "name": "Answer form",
                "points": 3,
                "description": "Returns the requested JSON schema with answer type, claim, ruling, selected evidence, calculation check, rejected alternatives, source paths, and reference trace.",
                "full_credit": "All required fields are present and the answer is compact structured JSON.",
                "partial_credit": "Minor naming or formatting errors, but the evidence ruling is recoverable.",
                "no_credit": "Does not return the required structured arbitration answer.",
            },
            {
                "name": "Direct burn-change source",
                "points": 4,
                "description": "Selects the Sentinel-2 dNBR file as the direct burn-change source and reports its product role.",
                "full_credit": "Selects data/physical_hazard/physical_hazard_008_Sentinel-2_SR_Harmonized_dNBR.json with correct dNBR modality and pre/post windows.",
                "partial_credit": "Selects a remote-sensing file but misses product role or one window detail.",
                "no_credit": "Selects annual embedding, heat, report, or exposure files as the direct burn-change source.",
            },
            {
                "name": "Temporal alignment",
                "points": 3,
                "description": "Uses the official event window and computes overlap with the dNBR post window.",
                "full_credit": "Reports 62 event days, 62 overlapping dNBR post-window days, and 29 extra post-event days.",
                "partial_credit": "Gets the overlap direction right with a small inclusive-day counting error.",
                "no_credit": "Ignores event-window alignment or uses the wrong window.",
            },
            {
                "name": "dNBR calculations",
                "points": 4,
                "description": "Reports dNBR statistics and compact contrast calculations.",
                "full_credit": "Reports dNBR max, mean, min, stdDev and the 0.903857 max-minus-mean, 19.494223 max-over-mean, and 11.051036 z-like contrast values.",
                "partial_credit": "Most dNBR values are correct with minor rounding or one calculation error.",
                "no_credit": "Does not compute from the dNBR stats.",
            },
            {
                "name": "Embedding rejection",
                "points": 3,
                "description": "Rejects the annual satellite-embedding cosine-change file for role and temporal mismatch.",
                "full_credit": "Explains that the embedding file is a generic 2018-to-2019 cosine-change product, not dNBR or event-window burn severity, and reports the numeric source-swap consequence.",
                "partial_credit": "Rejects the embedding file but gives incomplete numeric or temporal support.",
                "no_credit": "Treats the embedding metric as interchangeable with dNBR.",
            },
            {
                "name": "Fire-weather context boundary",
                "points": 2,
                "description": "Keeps Open-Meteo heat and humidity evidence in a context-only role.",
                "full_credit": "Reports 42.2 C and 8 percent RH as context but not as burn-scar measurement.",
                "partial_credit": "Mentions heat context without the numeric anchor.",
                "no_credit": "Uses weather data as direct remote-sensing change evidence.",
            },
            {
                "name": "Scope and provenance",
                "points": 1,
                "description": "Uses package-relative paths only and avoids external evidence, hidden answers, broad disaster prose, and outside burn-severity thresholds.",
                "full_credit": "All provenance and scope constraints are followed.",
                "partial_credit": "Minor prose overreach without changing the answer.",
                "no_credit": "Uses web evidence, hidden answers, absolute answer paths, or external severity thresholds.",
            },
        ],
    }


def main() -> None:
    root = package_root()
    event = read_json(root, "metadata/event.json")
    anchor = read_json(root, EVENT_WINDOW_PATH)
    dnbr = read_json(root, DNBR_PATH)
    embedding = read_json(root, EMBEDDING_PATH)
    openmeteo = read_json(root, OPENMETEO_PATH)

    event_start = anchor["temporal_window"]["start_date"]
    event_end = anchor["temporal_window"]["end_date"]
    pre_start, pre_end = dnbr["windows"]["pre"]
    post_start, post_end = dnbr["windows"]["post"]

    event_day_count = inclusive_days(event_start, event_end)
    post_overlap = overlap_days(event_start, event_end, post_start, post_end)
    post_extra_after_event = max(0, (parse_date(post_end) - parse_date(event_end)).days)

    dnbr_stats = dnbr["stats"]
    dnbr_max = dnbr_stats["sentinel2_dnbr_max"]
    dnbr_mean = dnbr_stats["sentinel2_dnbr_mean"]
    dnbr_min = dnbr_stats["sentinel2_dnbr_min"]
    dnbr_std = dnbr_stats["sentinel2_dnbr_stdDev"]

    max_minus_mean = dnbr_max - dnbr_mean
    max_over_mean = dnbr_max / dnbr_mean
    z_like = max_minus_mean / dnbr_std

    embedding_stats = embedding["stats"]
    embedding_max = embedding_stats["alphaearth_1_minus_cosine_max"]
    embedding_mean = embedding_stats["alphaearth_1_minus_cosine_mean"]

    hourly_temp = openmeteo["hourly"]["temperature_2m"]
    hottest_hour_index = max(range(len(hourly_temp)), key=hourly_temp.__getitem__)
    hourly_max_temp = hourly_temp[hottest_hour_index]
    rh_at_hourly_tmax = openmeteo["hourly"]["relative_humidity_2m"][hottest_hour_index]

    primary_gt = {
        "answer_type": "remote_sensing_change_attribution",
        "claim": "direct_package_evidence_of_localized_burn_scar_change",
        "ruling": "direct_dnbr_supports_localized_burn_change_but_not_exact_area_or_impact",
        "selected_evidence": {
            "path": DNBR_PATH,
            "modality": f"{dnbr['dataset']} dNBR",
            "pre_window": [pre_start, pre_end],
            "post_window": [post_start, post_end],
            "post_window_overlap_with_event_days": post_overlap,
            "post_window_extra_days_after_event": post_extra_after_event,
            "stats": {
                "dnbr_max": round6(dnbr_max),
                "dnbr_mean": round6(dnbr_mean),
                "dnbr_min": round6(dnbr_min),
                "dnbr_stdDev": round6(dnbr_std),
            },
        },
        "calculation_check": {
            "event_window_days": event_day_count,
            "dnbr_max_minus_mean": round6(max_minus_mean),
            "dnbr_max_over_mean": round6(max_over_mean),
            "dnbr_max_z_like_above_mean": round6(z_like),
        },
        "rejected_or_insufficient_alternatives": {
            EMBEDDING_PATH: {
                "role_error": "generic annual embedding change for 2018-to-2019, not a dNBR burn-index product and not isolated to the official event/post-fire window",
                "numeric_consequence_if_swapped": {
                    "wrong_metric_max": round6(embedding_max),
                    "wrong_metric_mean": round6(embedding_mean),
                    "wrong_max_minus_selected_dnbr_max": round6(embedding_max - dnbr_max),
                    "wrong_mean_minus_selected_dnbr_mean": round6(embedding_mean - dnbr_mean),
                },
            },
            OPENMETEO_PATH: {
                "role_error": "local heat and humidity can support fire-weather context but cannot measure burn scar or surface change",
                "numeric_consequence_if_swapped": {
                    "hourly_max_temperature_c": round(float(hourly_max_temp), 1),
                    "relative_humidity_at_hourly_tmax_percent": rh_at_hourly_tmax,
                },
            },
        },
        "source_paths": {
            "event_window": EVENT_WINDOW_PATH,
            "direct_burn_change": DNBR_PATH,
            "rejected_embedding_change": EMBEDDING_PATH,
            "fire_weather_context_only": OPENMETEO_PATH,
        },
        "reference_trace": [
            "Read the locked event anchor and take the official window as 2019-12-01 through 2020-01-31, inclusive.",
            "Inspect the Sentinel-2 dNBR file and verify that its post window 2019-12-01 through 2020-02-29 overlaps all 62 official event days.",
            "Compute dNBR contrast from the Sentinel-2 stats: max minus mean = 0.903857, max over mean = 19.494223, and z-like contrast = 11.051036.",
            "Reject the annual embedding change as a generic 2018-to-2019 cosine-change product and reject Open-Meteo as fire-weather context only.",
        ],
    }

    result = {
        "schema_version": "1.0",
        "task_id": TASK_ID,
        "event_id": PACKAGE_ID,
        "target_family": "remote_sensing_change_attribution",
        "task_type": "expert_source_arbitration",
        "evaluation_mode": "hybrid",
        "difficulty_level": "L3",
        "primary_gt": primary_gt,
        "rubric": build_rubric(),
        "event": {
            "package_id": PACKAGE_ID,
            "event_name": event["event_name"],
            "hazard_family": event["hazard_family"],
            "event_date_or_window": f"{event_start} to {event_end}",
        },
        "decision_rule": {
            "summary": "Select the direct package-local burn-change product, compute its event-window alignment and dNBR contrast, and reject wrong-role source swaps.",
            "requires_computation": True,
            "required_reasoning_axes": [
                "event_window_overlap",
                "remote_sensing_product_role",
                "dnbr_stats_and_contrast",
                "source_swap_consequence",
                "context_only_weather_boundary",
            ],
            "forbidden_shortcuts": [
                "treating annual embedding cosine change as dNBR",
                "using heat or humidity as burn-scar measurement",
                "using external burn severity thresholds",
                "claiming exact burn area or impact not present in the package",
                "web search or hidden-answer lookup",
            ],
        },
        "key_values": {
            "official_event_window": {
                "start_date": event_start,
                "end_date": event_end,
                "inclusive_days": event_day_count,
                "source_path": EVENT_WINDOW_PATH,
            },
            "selected_dnbr_product": {
                "source_path": DNBR_PATH,
                "dataset": dnbr["dataset"],
                "pre_count": dnbr["counts"]["pre_count"],
                "post_count": dnbr["counts"]["post_count"],
                "post_window_overlap_with_event_days": post_overlap,
                "post_window_extra_days_after_event": post_extra_after_event,
            },
            "dnbr_stats_raw": dnbr_stats,
            "embedding_stats_raw": embedding_stats,
            "openmeteo_context_values": {
                "hourly_max_temperature_c": round(float(hourly_max_temp), 1),
                "relative_humidity_at_hourly_tmax_percent": rh_at_hourly_tmax,
            },
        },
        "numeric_tolerances": {
            "dnbr_max": {"target": primary_gt["selected_evidence"]["stats"]["dnbr_max"], "absolute_tolerance": 0.000001},
            "dnbr_mean": {"target": primary_gt["selected_evidence"]["stats"]["dnbr_mean"], "absolute_tolerance": 0.000001},
            "dnbr_min": {"target": primary_gt["selected_evidence"]["stats"]["dnbr_min"], "absolute_tolerance": 0.000001},
            "dnbr_stdDev": {"target": primary_gt["selected_evidence"]["stats"]["dnbr_stdDev"], "absolute_tolerance": 0.000001},
            "dnbr_max_minus_mean": {
                "target": primary_gt["calculation_check"]["dnbr_max_minus_mean"],
                "absolute_tolerance": 0.000001,
            },
            "dnbr_max_over_mean": {
                "target": primary_gt["calculation_check"]["dnbr_max_over_mean"],
                "absolute_tolerance": 0.000001,
            },
            "dnbr_max_z_like_above_mean": {
                "target": primary_gt["calculation_check"]["dnbr_max_z_like_above_mean"],
                "absolute_tolerance": 0.000001,
            },
        },
        "severity_interpretation": {
            "supports": [
                "direct package-local dNBR evidence of localized burn-scar change",
                "event-window/post-fire temporal overlap for the dNBR product",
                "fire-weather context from local heat and low humidity",
            ],
            "do_not_overclaim": [
                "exact burn area",
                "population or infrastructure impact",
                "burn-severity class based on external thresholds",
                "annual embedding change as a burn-index substitute",
                "heat values as direct burn-scar measurement",
            ],
        },
        "provenance": {
            "computed_by": "compute_gt.py",
            "source_files": [
                "metadata/event.json",
                EVENT_WINDOW_PATH,
                DNBR_PATH,
                EMBEDDING_PATH,
                OPENMETEO_PATH,
            ],
        },
    }

    output_path = Path(__file__).resolve().parent / "computed_gt.json"
    output_path.write_text(json.dumps(result, indent=2, ensure_ascii=True) + "\n", encoding="utf-8")


if __name__ == "__main__":
    main()
